import React, { useState } from 'react';
import { LogIn, Mail, Lock } from 'lucide-react';

function Login() {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    const onSubmit = async () => {
        e.preventDefault();
        const loginDetails = {email, password};

        
        console.log("Logging in with:", loginDetails);
        alert("Login successful");
        
        // In your actual app:
        // try {
        //     const response = await axios.post("http://localhost:8080/login", loginDetails);
        //     if (response.data.id) {
        //         localStorage.setItem('userId', response.data.id);
        //         alert("Login successful");
        //         window.location.reload();
        //     } else {
        //         alert('Invalid credentials');
        //     }
        // } catch (err) {
        //     alert('Invalid credentials');
        //     window.location.reload();
        // }
    }

    return (
        <div style={{
            minHeight: '100vh',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            padding: '20px'
        }}>
            <div style={{
                background: 'white',
                padding: '40px',
                borderRadius: '15px',
                boxShadow: '0 10px 40px rgba(0,0,0,0.2)',
                width: '100%',
                maxWidth: '420px'
            }}>
                <div style={{ textAlign: 'center', marginBottom: '35px' }}>
                    <div style={{
                        width: '70px',
                        height: '70px',
                        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                        borderRadius: '50%',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        margin: '0 auto 20px'
                    }}>
                        <LogIn size={35} color="white" />
                    </div>
                    <h1 style={{
                        fontSize: '28px',
                        color: '#333',
                        margin: '0 0 10px 0',
                        fontWeight: '600'
                    }}>Welcome Back</h1>
                    <p style={{
                        color: '#666',
                        fontSize: '14px',
                        margin: 0
                    }}>Login to your account</p>
                </div>

                <div>
                    <div style={{ marginBottom: '20px' }}>
                        <label style={{
                            display: 'block',
                            marginBottom: '8px',
                            color: '#333',
                            fontSize: '14px',
                            fontWeight: '500'
                        }}>
                            <Mail size={16} style={{ verticalAlign: 'middle', marginRight: '5px' }} />
                            Email Address
                        </label>
                        <input
                            type="email"
                            name="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="Enter your email"
                            style={{
                                width: '100%',
                                padding: '12px 15px',
                                border: '2px solid #e0e0e0',
                                borderRadius: '8px',
                                fontSize: '14px',
                                transition: 'all 0.3s',
                                outline: 'none',
                                boxSizing: 'border-box'
                            }}
                            onFocus={(e) => e.target.style.borderColor = '#667eea'}
                            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
                        />
                    </div>

                    <div style={{ marginBottom: '25px' }}>
                        <label style={{
                            display: 'block',
                            marginBottom: '8px',
                            color: '#333',
                            fontSize: '14px',
                            fontWeight: '500'
                        }}>
                            <Lock size={16} style={{ verticalAlign: 'middle', marginRight: '5px' }} />
                            Password
                        </label>
                        <input
                            type="password"
                            name="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="Enter your password"
                            style={{
                                width: '100%',
                                padding: '12px 15px',
                                border: '2px solid #e0e0e0',
                                borderRadius: '8px',
                                fontSize: '14px',
                                transition: 'all 0.3s',
                                outline: 'none',
                                boxSizing: 'border-box'
                            }}
                            onFocus={(e) => e.target.style.borderColor = '#667eea'}
                            onBlur={(e) => e.target.style.borderColor = '#e0e0e0'}
                        />
                    </div>

                    <div style={{
                        display: 'flex',
                        justifyContent: 'flex-end',
                        marginBottom: '25px'
                    }}>
                        <a href="/forgot-password" style={{
                            color: '#667eea',
                            textDecoration: 'none',
                            fontSize: '13px',
                            fontWeight: '500'
                        }}>
                            Forgot Password?
                        </a>
                    </div>

                    <button
                        onClick={onSubmit}
                        style={{
                            width: '100%',
                            padding: '14px',
                            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                            color: 'white',
                            border: 'none',
                            borderRadius: '8px',
                            fontSize: '16px',
                            fontWeight: '600',
                            cursor: 'pointer',
                            transition: 'all 0.3s',
                            boxShadow: '0 4px 15px rgba(102, 126, 234, 0.4)'
                        }}
                        onMouseOver={(e) => {
                            e.target.style.transform = 'translateY(-2px)';
                            e.target.style.boxShadow = '0 6px 20px rgba(102, 126, 234, 0.6)';
                        }}
                        onMouseOut={(e) => {
                            e.target.style.transform = 'translateY(0)';
                            e.target.style.boxShadow = '0 4px 15px rgba(102, 126, 234, 0.4)';
                        }}
                    >
                        Login
                    </button>
                </div>

                <div style={{
                    textAlign: 'center',
                    marginTop: '25px',
                    paddingTop: '25px',
                    borderTop: '1px solid #e0e0e0'
                }}>
                    <p style={{
                        fontSize: '14px',
                        color: '#666',
                        margin: 0
                    }}>
                        Don't have an account?{' '}
                        <a href="/register" style={{
                            color: '#667eea',
                            textDecoration: 'none',
                            fontWeight: '600'
                        }}>
                            Register here
                        </a>
                    </p>
                </div>
            </div>
        </div>
    );
}

export default Login;
